  if (tasks.length === 0) return 0;

  const counts = new Map<string, number>();
  for (const task of tasks) counts.set(task, (counts.get(task) ?? 0) + 1);

  const frequencies = [...counts.values()];
  const busiest = Math.max(...frequencies);
